import React from "react";
import { FaMobileAlt } from "react-icons/fa";
import { apiPost } from "../common/api";
import Loader from "../common/Loader";
import withRouter from "../common/withRouter";

class LoginPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      mobile: "",
      loading: false,
      errorMessage: "",
    };

    this.handleChange = this.handleChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
    this.validateMobile = this.validateMobile.bind(this);
  }

  componentDidMount() {
    const navOuter = document.querySelector(".nav-outer");

    if (navOuter) {
      navOuter.style.display = "none";
    }
  }

  componentWillUnmount() {
    const navOuter = document.querySelector(".nav-outer");

    if (navOuter) {
      navOuter.style.display = "";
    }
  }

  validateMobile(mobile) {
    if (!mobile) {
      return "شماره موبایل الزامی است";
    }

    if (!/^[0-9]+$/.test(mobile)) {
      return "شماره موبایل باید فقط شامل عدد باشد";
    }

    if (mobile.length !== 11) {
      return "شماره موبایل باید دقیقاً ۱۱ رقم باشد";
    }

    if (!mobile.startsWith("09")) {
      return "شماره موبایل باید با ۰۹ شروع شود";
    }

    return "";
  }

  handleChange(e) {
    let value = e.target.value;

    // فقط عدد
    value = value.replace(/\D/g, "");

    // حداکثر 11 رقم
    value = value.slice(0, 11);

    this.setState({
      mobile: value,
      errorMessage: "",
    });
  }

  handleSubmit(e) {
    e.preventDefault();

    const mobile = this.state.mobile.trim();

    const error = this.validateMobile(mobile);

    if (error) {
      this.setState({
        errorMessage: error,
      });

      return;
    }

    this.setState({
      loading: true,
      errorMessage: "",
    });

    apiPost("/login", {
      mobile,
    })
      .then((json) => {
        if (json.status === "1") {
          const userId =
            json.id ||
            json.user_id ||
            json.data?.id ||
            json.data?.user_id ||
            json.user?.id ||
            json.data?.user?.id;

          if (!userId) {
            this.setState({
              loading: false,
              errorMessage:
                "شناسه کاربر از سرور دریافت نشد",
            });

            return;
          }

          localStorage.setItem(
            "pending_mobile",
            mobile
          );

          localStorage.setItem(
            "user_id",
            String(userId)
          );

          this.setState({
            loading: false,
          });

          this.props.navigate("/verify-code");
        } else {
          this.setState({
            loading: false,
            errorMessage:
              json.message || "شماره موبایل معتبر نیست",
          });
        }
      })
      .catch((error) => {
        console.error("LOGIN ERROR:", error);

        this.setState({
          loading: false,
          errorMessage:
            "ارتباط با سرور برقرار نشد",
        });
      });
  }

  render() {
    const {
      mobile,
      loading,
      errorMessage,
    } = this.state;

    return (
      <div dir="rtl">
        {loading && <Loader />}

        <div
          className="container-fluid px-3 pt-5"
          style={{
            maxWidth: 480,
            margin: "0 auto",
          }}
        >
          <h1 className="fs-6 fw-semibold text-dark text-center mb-4">
            ورود به سیستم
          </h1>

          <img
            src="../img/aaa.png"
            alt="logo"
            className="w-100 my-3 rounded"
          />

          <form onSubmit={this.handleSubmit} noValidate>
            <div
              className={`d-flex align-items-center justify-content-between gap-2 border rounded-3 px-3 py-3 mb-3 bg-white ${
                errorMessage ? "border-danger" : ""
              }`}
            >
              <input
                type="tel"
                inputMode="numeric"
                maxLength={11}
                required
                placeholder="شماره موبایل"
                value={mobile}
                onChange={this.handleChange}
                className="form-control border-0 shadow-none text-end p-0"
                disabled={loading}
              />

              <FaMobileAlt
                className={
                  errorMessage
                    ? "text-danger"
                    : "text-secondary"
                }
                size={18}
              />
            </div>

            {errorMessage && (
              <div className="text-danger small text-center mb-3">
                {errorMessage}
              </div>
            )}

            <button
              type="submit"
              className="btn btn-primary w-100 rounded-3 py-3"
              disabled={loading}
            >
              {loading
                ? "در حال ارسال..."
                : "دریافت کد تایید"}
            </button>
          </form>
        </div>
      </div>
    );
  }
}

export default withRouter(LoginPage);
